do $$
declare
  v_payload jsonb := $subjectskill${"skill_slug":"subject-lesson-design-music","source_skill_name":"music-public-lesson-design","version_label":"v2.0.0","snapshot_hash":"f4420c57c4549172f4cba8adfdec328bf5973d1c7e944b9ae03c9de143dfe049","instructions":"---\nname: music-public-lesson-design\ndescription: Design complete primary, junior-secondary, or senior-secondary music public lessons from verified scores, recordings, textbooks, and cultural sources. Use for 音乐/艺术·音乐公开课、优质课、展示课、赛课 involving listening and appraisal, singing, instrumental performance, ensemble, rhythm and movement, improvisation, composition, music-and-culture inquiry, or integrated arts; requires repeated purposeful listening, audible musical evidence, individual musicianship evidence, rehearsal-feedback-reperformance, healthy voice and hearing, cultural provenance, and copyright boundaries.\n---\n\n# 音乐公开课设计\n\n从音响出发，让学生在“聆听—感知—用音乐语言描述—表现/创造—再聆听比较—反馈修订”中形成音乐经验。背景故事、视频、教师独奏、舞台效果和齐声回答只能辅助，不能替代学生对节奏、旋律、力度、速度、音色、织体、结构和风格的听觉证据。\n\n## 运行门禁\n\n1. 核对学段、年级、教材版本、单元、作品/歌曲、课型、课时，并获得教材页、经校勘乐谱、合法音频/视频、歌词译文和文化来源。\n2. 当前项目没有音乐教材；仅有课题名时先列缺失项，不猜曲式、调式、拍号、速度、配器、歌词、演唱技法、作者背景或音频时间点。\n3. 课前核验音源版本与时码、调/音域、伴奏、乐器数量、音响音量、空间、身体活动与乐器安全；变声期、听觉/嗓音、行动和感官差异须有等价路径。\n4. 必读 [主流模式](references/mainstream-models.md)、[输出模板](references/output-template.md)、与学段匹配的样例和 [来源边界](references/sources-and-boundaries.md)。\n\n## 工作流\n\n### 1. 建立作品—任务—证据地图\n\n分析作品版本、文化语境、体裁/形式、可听辨的音乐要素、困难片段和学生最终音乐行动。每个解释必须能回到具体音响、乐谱位置或演唱/演奏变化；情绪联想可以多元，但不能脱离音乐证据任意讲故事。\n\n### 2. 诊断音乐起点\n\n用短音响比较、节拍/节奏模仿、主题辨识、呼吸/发声、视唱/演奏或结构图诊断。避免只问术语定义；记录每人能否听出、做出、说出和修订。\n\n### 3. 确定核心增长\n\n> 学生从“笼统说好听/会跟唱”，走向“能听辨并用证据描述某音乐特征，运用相应技能表现或创造，依据听觉反馈修订，并在文化语境中解释其意义”。\n\n目标2—4项，对齐个人听辨标记、节奏/旋律回声、演唱演奏片段、结构图、创编版本、排练日志、音乐评论或迁移选择。\n\n### 4. 选择主导模式\n\n- 听赏与评述；\n- 演唱建构；\n- 器乐/合奏与合作表现；\n- 节奏、律动与综合表演；\n- 即兴与音乐编创；\n- 民族民间/戏曲与文化语境；\n- 音乐项目、跨艺术与社会应用。\n\n按 [主流模式](references/mainstream-models.md) 选一条主线。低年级重多感官听觉体验，高年级逐步增加乐谱、结构、风格、创作技法和文化解释。\n\n### 5. 设计多次有目的聆听\n\n同一关键片段至少安排两次功能不同的聆听：首次整体感受/预测，后续聚焦要素、结构或表现作用，再以演唱、演奏、律动、图示或创编验证。每次聆听前给单一可执行任务，聆听中少讲解，聆听后先留个体证据。\n\n### 6. 组织排练—反馈—再表现\n\n把难点拆成可听可做的最小单元，教师示范后迅速交给学生；同伴反馈只依据节拍稳定、音高/节奏、音色、呼吸、咬字、力度、句法、配合和风格等可观察标准。保留首版与修订版，不能以少数特长生示范代替全员成长。\n\n### 7. 复核\n\n- 音响是否先于背景知识，讲解是否服务再次聆听；\n- 所有曲式、调式、乐器、时码和文化事实是否与当前版本一致；\n- 每人是否有听辨、表现/创造和修订证据；\n- 齐唱/合奏是否掩盖个体困难，是否有分层和轮换；\n- 评价是否看音乐质量与变化，而非音量、热闹、服装或个人天赋；\n- 是否保护嗓音/听力、尊重变声期、文化主体和版权；\n- 时间是否给足完整聆听、有效练习与复演。\n\n## 输出要求\n\n严格使用 [输出模板](references/output-template.md) 十三部分，Markdown 输出。样例仅示范结构与音乐证据链，不替代当前教材、乐谱和音源；证据不足时停止完整生成并列最小补充清单。","input_contract":{"format":"music_public_lesson_input_v1","required":["stage","subject","grade","volume","unit","topic","lesson_type"],"supported_stages":["小学","初中","高中"],"evidence_gate":"verified_textbook_score_recording_and_cultural_sources_required"},"output_contract":{"format":"music_public_lesson_markdown_v1","required_sections":["课程基本信息","单元与教材定位","作品、音响与文化分析","学情与音乐起点","核心增长与目标—任务—证据","重难点与音乐实践链","主导模式与公开课主线","音源乐谱、器材、安全与版权","听辨、排练与评价工具","教学流程","板书与音乐成果","量规、差异化与作业","反思与核验"],"lesson_flow_required":["环节功能/对应目标","音响/谱例范围与时码","聆听/表现指令","个体先行证据","合作必要性","教师行为与示范边界","学生听唱奏动创行动","音乐/文化支架","产出","不同听感/典型困难","评价与反馈分支","音乐要素与整体表达","文化/版权/安全边界","阶段成果与过渡","时间核算"]},"source_metadata":{"source_package":"music-public-lesson-design","source_kind":"repository_skill_source","source_file_count":8,"runtime_reference_count":6,"source_skill_hash":"8c64e1fade83b8dd317a4ea9ed52b02adf06b4891aa38daadd4eaaf02624cfae"},"references":[{"path":"references/mainstream-models.md","name":"音乐公开课主流教学模式","description":"七类音乐模式、分学段实践、听觉证据和失败信号","media_type":"text/markdown","content":"# 音乐公开课主流教学模式\n\n| 主导模式 | 核心循环 | 必须证据 | 失败信号 |\n|---|---|---|---|\n| 听赏与评述 | 整体聆听→个人反应→聚焦要素→主题/结构追踪→比较复听→证据化评述 | 听辨图、时码/乐谱位置、音乐要素—作用解释 | 先讲背景后播放；只说情绪无音响证据 |\n| 演唱建构 | 听辨范唱→节奏/旋律/歌词处理→分句学唱→难点诊断→完整表现→录听反馈→复唱 | 个体短句、首版/复唱、呼吸音准节奏等反馈 | 一遍遍齐唱；追求响亮；教师代唱 |\n| 器乐/合奏 | 声部目标→基本技法→分层分声部→合奏听平衡→互评→再合奏 | 个体节奏/音型、声部谱、合奏前后录音 | 特长生包办；只求不断拍；无声部倾听 |\n| 节奏律动/综合表演 | 节拍感知→身体/声势模仿→音乐要素对应动作→组合→随乐修订→解释 | 稳定节拍、动作—要素对应、个人节奏证据 | 动作热闹但与音乐无关；舞蹈遮蔽聆听 |\n| 即兴与编创 | 约束/素材→模仿变形→个体试作→组合→演出/录音→按音乐标准修订 | 动机/节奏素材、版本差异、选择理由 | 自由等于随意；只评创意故事不听音乐 |\n| 文化语境研习 | 先听音乐→识别风格证据→来源/功能/场合→比较版本→尝试表现→反思文化边界 | 文化来源、音响比较、风格证据 | 民族音乐奇观化；用服饰故事替代音乐 |\n| 音乐项目/跨艺术 | 真实用途→受众/约束→选曲/创作→排练制作→受众测试→版权核验→修订展示 | 任务书、排练日志、受众反馈、授权清单 | 汇演排节目；技术包装取代音乐学习 |\n\n## 共同循环\n\n`音响整体→个体可见反应→聚焦音乐要素→表现/图示/创编验证→反馈→再次聆听/表现→文化与迁移`。义务教育艺术课标的音乐内容为欣赏、表现、创造、联系四类，课堂可有主次，但不能长期只剩背景讲授或模仿表演。\n\n## 学段适配\n\n- **小学1—2年级**：唱游·音乐，以聆听、歌唱、身体律动、图形线条和简易打击乐建立高低、长短、强弱、速度、音色、节拍经验；指令短、活动必须体现音乐性。\n- **小学3—6年级**：听赏评述、独唱合作演唱、独奏合作演奏、创编、跨艺术表演、生活音乐；逐渐用音乐术语和结构图支持听觉。\n- **初中**：增加主题/段落、体裁形式、调式风格、声部合作和文化比较；个性理解必须有音乐证据。\n- **高中**：依据鉴赏、歌唱、演奏、创作、音乐与舞蹈/戏剧等模块，提高作品分析、审美判断、二度创作和文化论证要求。\n\n## 硬性学科规则\n\n- 音乐先于图片/故事；视觉材料不得持续抢占听觉注意。\n- 情感是整体体验，元素分析用于返回整体，不把作品拆成术语清单。\n- 录音比较须获得课堂许可，限必要片段，不公开学生个人失误，课后按规则删除。\n- 演唱不超出学生安全音域，不以喊唱换音量；变声期可降调、轻声、节奏/器乐/指挥等价参与。\n- 民族民间、戏曲、宗教/仪式音乐须核来源、场合、语言发音与文化主体，不刻板模仿。","content_hash":"ac32a3e72c5ff85298f4a09f25a97affc1f0d5ca4e1d74dc6a9103c7b9624e9f","load_mode":"always","max_chars":1256,"sort_order":10,"metadata":{"source_package":"music-public-lesson-design","runtime_role":"discipline_reference"}},{"path":"references/output-template.md","name":"音乐公开课完整输出模板","description":"十三部分教案、作品音响分析、排练复演、安全版权与质量约束","media_type":"text/markdown","content":"# 音乐公开课完整输出模板\n\n## 一、课程基本信息\n学段/年级、教材版本、单元、作品/歌曲、课型时长、主导模式、课时、音源/乐谱版本、教材证据状态、待核项。\n\n## 二、单元与教材定位\n单元主题、前后听觉/技能经验、本课功能、教材正文/谱例/活动；只给标题时停止完整生成。\n\n## 三、作品、音响与文化分析\n写作者/来源、体裁、文化场合、版本、音域/调/拍/速度（按教材要求）、主题、段落/曲式、节奏旋律力度速度音色织体等可听证据、歌词/译文、困难片段、适合学生的表现/创造价值。每项标音频时码或谱例位置及待核边界。\n\n## 四、学情与音乐起点\n听觉经验、节拍节奏、音准、发声/器乐、读谱、审美表达、文化认识、变声期与感官/行动差异；给2—4分钟个体诊断和反馈分支。\n\n## 五、核心增长与目标—任务—证据\n一句增长；2—4项目标对应音乐任务、个体证据、成功标准、采集时点。至少覆盖听辨/描述、表现或创造、反馈修订、文化理解中的相应项。\n\n## 六、重难点与音乐实践链\n`整体聆听→聚焦听辨→音乐语言命名→表现/图示/创编验证→反馈→再聆听/再表现→文化与迁移`；写不能推出。\n\n## 七、主导模式与公开课主线\n模式理由、核心音乐问题、最终音乐成果、每次聆听功能、合作必要性、教师示范边界、学习性亮点与删除的表演性环节。\n\n## 八、音源乐谱、器材、安全与版权\n音源/乐谱版本、合法来源、时码、伴奏调与速度、设备/乐器、数量轮换、音量与听力、嗓音/变声期、动作空间、消毒维护、录音权限/删除、素材许可、无设备替代。\n\n## 九、听辨、排练与评价工具\n空白聆听地图、主题/结构图、歌词/谱例标注、声部分工、排练日志、首版—反馈—复演表、创编约束卡和音乐量规；不预填唯一情绪或完美结果。\n\n## 十、教学流程\n每环写功能、音响/谱例范围与时码、聆听指令、个体先行、教师行为、学生听/唱/奏/动/创行动、支架、产出、不同听感、典型困难、反馈分支、音乐要素与整体表达、文化边界、阶段成果/过渡、时间。总时长闭合，并出现至少一次基于反馈的复听或复演。\n\n## 十一、板书与音乐成果\n动态呈现主题/结构、音乐要素—音响证据—表现作用、首版/修订和文化语境；屏幕不取代听觉，关键谱例/图示可停留。\n\n## 十二、量规、差异化与作业\n至少四维3级：听辨证据、节奏/音准/技法、音乐表现、合作倾听、创编、文化解释、反馈修订。提供降调/简化声部/节奏或指挥替代、图形谱、文字音响描述、触觉节拍等目标等价路径。作业有合法音源和无设备替代，不强制公开录脸录声。\n\n## 十三、反思与核验\n收集个体听辨、首版/复演和解释证据；记录3类风险和修订。核验教材、谱/音源版本、时码、音乐术语、译音/发音、文化来源、音域音量、安全和版权。\n\n## 硬约束\n- 不以背景故事、视频画面或教师表演替代学生聆听。\n- 不写“一听就感到某唯一情绪”；个性理解须回到音响证据。\n- 不用反复齐唱/合奏掩盖个体困难，不以少数特长生代表全班。\n- 不把汇演效果、服装道具、音量和整齐度当成全部音乐评价。\n- 不虚构曲式、调式、配器、时码、歌词、文化事实和授权。","content_hash":"e863f70758339500ecf9995a3757698157ec525cf5adc0bbb35e47a2044f2432","load_mode":"always","max_chars":1307,"sort_order":20,"metadata":{"source_package":"music-public-lesson-design","runtime_role":"discipline_reference"}},{"path":"references/excellent-example-primary.md","name":"小学音乐优秀教案样例","description":"基于真实精品课题重构的速度听辨、律动验证与复演示范","media_type":"text/markdown","content":"# 小学音乐优秀教案参考样例\n\n> 依据2024部级精品课真实课题“感知音乐中的速度（一）——《森吉德玛》主题片断”及义务教育艺术课标机制原创重构，不复刻原获奖教案。正式实施须补当前教材谱例和合法音源，并据实际录音核准时码、速度层次、配器和结构。\n\n## 一、课程基本信息\n\n| 字段 | 内容 |\n|---|---|\n| 学段/年级 | 小学二年级 |\n| 课题 | 感知音乐中的速度——《森吉德玛》主题片断 |\n| 课型/时长 | 唱游·音乐/聆听与律动，40分钟 |\n| 主导模式 | 听赏与评述（辅以节奏律动） |\n| 核心问题 | 速度变化怎样让同一主题带来不同运动感？ |\n| 证据状态 | 课题可核；具体音响与谱例待教材/音源核准 |\n\n## 二、单元与教材定位\n\n本课适合学生已有快慢生活经验和稳定跟随基本拍感之后，把“动作快慢”转为“持续聆听音乐速度、用动作/图示表现并在复听中验证”。后续可迁移到力度、节拍等要素。教材单元、课时和作品信息以实际教材为准。\n\n## 三、作品、音响与文化分析\n\n- 只选择教材规定的两个对比鲜明主题片段，正式备课在表格中填写音源版本、起止时码和速度证据。\n- 学科焦点是速度，不提前用草原图片/故事规定唯一联想；学生先听，再用步幅、线条密度或速度词描述。\n- 同一/相关主题、配器、力度等是否变化须据谱/音源核验，不能把全部听感差异都归因速度。\n- 作品文化与作者背景在学生已有音响证据后简要补充，来源须核，不装扮或刻板模仿民族形象。\n\n## 四、学情与音乐起点\n\n学生能说快慢，但会随意加速、把“声音大”当“速度快”，或被视频画面带走。诊断3分钟：听两段无画面声音/节拍，个人用疏/密点表示快慢并跟拍。把力度当速度者以“同样轻声但拍点变密”对比例澄清。\n\n## 五、核心增长与目标—任务—证据\n\n**核心增长**：从凭画面/笼统感受说快慢，走向持续跟随速度，用音乐动作/图示举证，并根据复听修订。\n\n| 目标 | 任务 | 个体证据 | 成功标准 |\n|---|---|---|---|\n| 听辨速度 | 两片段无画面对比 | 个人疏密图与选择 | 跟随拍点而非音量判断 |\n| 表现差异 | 步行/手势/声势 | 每人一段稳定表现 | 动作快慢对应音乐，不抢拍 |\n| 解释作用 | 复听比较 | “我听到___所以___” | 引用速度及至少一个待核辅助要素 |\n| 迁移 | 新片段快判 | 出口卡 | 能听后选择动作并修订 |\n\n## 六、重难点与音乐实践链\n\n`无画面整体听→个体疏密图→稳定跟拍→聚焦速度→动作验证→交换表现→再次听辨修订→文化联系→迁移`。重点是持续感知速度；难点是区分速度与力度。不能把联想当作作品唯一意义。\n\n## 七、主导模式与公开课主线\n\n三次聆听功能不同：第一次整体判断，第二次跟拍/动作验证，第三次比较修订并注意还有哪些要素参与表达。公开课亮点是学生图示和动作由不稳定到稳定，而非教师带来的视频和舞台布景。\n\n## 八、音源乐谱、器材、安全与版权\n\n正式教案填音源/谱例来源、版本、两片段时码、播放音量；准备疏密点卡、沙锤/手鼓或无器材声势。音量先用声级规范/现场安全标准核准，不近扬声器；行走范围和方向标线，坐姿/手部动作可等价替代。乐器轮换，每人有跟拍机会。音频只用于授权课堂，不录制传播。\n\n## 九、听辨、排练与评价工具\n\n| 聆听轮次 | 任务 | 我的图示/动作 | 听到的证据 | 与第一次相比 | 我要修订 |\n|---|---|---|---|---|---|\n| 1 | 整体快慢 |  |  |  |  |\n| 2 | 跟拍验证 |  |  |  |  |\n| 3 | 比较与要素 |  |  |  |  |\n\n图示不预填标准画法；只要能稳定对应音乐并解释即可。\n\n## 十、教学流程\n\n### 环节1｜声音快慢诊断（3分钟）\n无画面播放两段经核声音，学生个体疏密点+跟拍。教师不先说答案。\n\n### 环节2｜第一遍整体聆听（5分钟）\n播放片段A/B，学生只完成“更舒展/更紧凑/暂不确定”和图示。说“因为画面”者被提醒本轮没有画面；说“更响所以更快”者留作下一环验证。\n\n### 环节3｜稳定拍点与动作验证（7分钟）\n全员先坐姿拍点，再分半班用行走/手势表现，交换。抢拍者缩小动作回到拍点；行动困难者用手指/图卡；固定几个学生领舞被禁止。\n\n### 环节4｜速度还是力度（6分钟）\n教师用同一节奏做“快而轻/慢而强”四格示范，学生个体判断后再听作品片段，分别标速度/力度证据。若音源中力度也变化，写“共同参与”，不把复杂听感强归单因。\n\n### 环节5｜小组设计两版音乐动作（8分钟）\n每人先画一项动作，再组合同一主题的慢/快两版；动作必须能被拍点约束。观察组按“拍点稳定、速度对应、每人参与”反馈，不能只说整齐好看。\n\n### 环节6｜再次聆听与修订表现（6分钟）\n小组随音源首演→收到一条音乐反馈→修订复演。保留修改点；若第一版已稳，需说明证据后做细化而非强迫制造错误。\n\n### 环节7｜文化联系与迁移出口（5分钟）\n在音响证据之后，教师用经核短信息说明作品来源/语境。播放新片段，学生独立完成：`我用___图/动作，因为拍点___；不能只根据___判断。`收束到再听验证。\n\n**总时间：3+5+7+6+8+6+5=40分钟。**\n\n## 十一、板书与音乐成果\n```text\n听速度：单位时间里的拍点疏 / 密\n第一次听 → 图示 → 跟拍/动作验证 → 速度 vs 力度 → 修订复演\n快 ≠ 大声；慢 ≠ 轻声\n联想可以不同，音乐证据要说清\n```\n\n## 十二、量规、差异化与作业\n\n| 维度 | 3级 | 2级 | 1级 |\n|---|---|---|---|\n| 听辨 | 持续跟随并区分速度/力度 | 能判断快慢 | 靠画面/音量猜 |\n| 表现 | 动作/图示稳定对应音乐 | 大体对应 | 动作与音响脱节 |\n| 解释 | 引用拍点和作品证据 | 能说速度词 | 只说好听/像什么 |\n| 修订 | 按音乐反馈有效复演 | 有修改 | 只改队形/道具 |\n\n听觉困难者结合振动/视觉节拍和教师核准辅助；低视力者用触觉点卡，行动困难者坐姿声势，害怕独演者以个人图示+集体表现证明。作业在生活中找两段合法可聆听音乐，用疏密图表示速度并写是否还有力度变化；无设备者记录校园音乐，10分钟。\n\n## 十三、反思与核验\n- 收集个人图示、跟拍观察、两版表现和出口卡。\n- 风险：画面先入为主、动作喧宾夺主、快慢与强弱混淆；用无画面首听、拍点标准、四格对比纠偏。\n- 核验教材、曲名作者/文化、音源版本时码、速度/力度事实、音量和空间安全、版权。\n- 下一课迁移到力度或结构，继续先听后命名。","content_hash":"8e9394e4b9530e998c7b4edebf302265feb5730e442f62f96af16f4152275438","load_mode":"always","max_chars":2812,"sort_order":30,"metadata":{"source_package":"music-public-lesson-design","runtime_role":"discipline_reference","stages":["小学"]}},{"path":"references/excellent-example-junior.md","name":"初中音乐优秀教案样例","description":"基于真实精品课题重构的主题期待、音响证据与微型创编示范","media_type":"text/markdown","content":"# 初中音乐优秀教案参考样例\n\n> 依据2022部级精品课真实课题“第九十四（‘惊愕’）交响曲”及课标听赏机制原创重构，不复刻获奖教案。具体乐章、主题、曲式、配器、力度事件和时码必须据当前教材与选用录音核准。\n\n## 一、课程基本信息\n| 字段 | 内容 |\n|---|---|\n| 学段/年级 | 初中八年级 |\n| 课题 | 第九十四（“惊愕”）交响曲：期待是怎样被打破的 |\n| 课型/时长 | 听赏与评述，45分钟 |\n| 主导模式 | 听赏与评述 |\n| 核心问题 | 作曲家怎样通过重复、力度/音色等对比改变我们的听觉期待？ |\n| 证据状态 | 课题可核；教材乐章、谱例和音源时码待核 |\n\n## 二、单元与教材定位\n本课在学生已有主题、力度、音色和段落经验上，推进到追踪“重复—变化—期待”的关系；后续可迁移至变奏、交响体裁或其他幽默表达。不得仅因副标题讲趣闻。\n\n## 三、作品、音响与文化分析\n- 按当前教材确认所选乐章和节选，制作合法音源时码表。\n- 学生先无标题聆听，标主题出现和变化，再探讨标题/轶事；轶事来源若不可靠只标传说，不当作理解作品的唯一钥匙。\n- 所谓“惊愕”须回到具体力度、配器/音色、织体、休止或结构位置（以当前谱/音源核准），并讨论前文如何建立期待。\n- 文化语境用于解释交响音乐的聆听场合和作曲实践，不代替音响分析。\n\n## 四、学情与音乐起点\n学生容易只等“突然很响”而忽略期待如何形成，或把副标题故事当全部内容。诊断4分钟：听一段重复后变化的经核短例，每人画主题轨迹并圈意外位置。只写“吓一跳”者补“之前听到了怎样的重复/稳定”。\n\n## 五、核心增长与目标—任务—证据\n**核心增长**：从捕捉一个突发效果，走向追踪主题重复/变化和音乐要素证据，解释听觉期待怎样形成、打破并继续发展。\n\n| 目标 | 任务 | 个体证据 | 标准 |\n|---|---|---|---|\n| 识别主题结构 | 多次听写主题卡 | 个人结构线 | 标出主题/变化/位置 |\n| 分析表现手段 | 聚焦复听 | 时码/谱例证据卡 | 至少两项要素及作用 |\n| 验证解释 | 声势/器乐微型表现 | 首版/复演 | 能建立并打破期待 |\n| 迁移评述 | 新片段短评 | CER | 结论与音响证据一致 |\n\n## 六、重难点与音乐实践链\n`无标题整体听→主题捕捉→结构追踪→聚焦意外前后→音乐要素分析→微型表现验证→反馈复演→文化语境→迁移评述`。难点是“意外”来自关系，不是孤立大声。\n\n## 七、主导模式与公开课主线\n四次聆听分别承担整体反应、主题追踪、意外点证据、完整结构复核。学生的声势/器乐实验用来验证“先建立规律再改变”，不是编节目。最终为带位置证据的个人音乐短评。\n\n## 八、音源乐谱、器材、安全与版权\n正式填写录音版本、总时长、片段时码、谱例出处、播放音量与使用许可；准备主题卡、结构条和小打击乐/声势。突然力度对比不得以危险音量制造效果。乐器轮换，变声期不强制高声模唱。录音只比较小组整体、经同意且课后删除。\n\n## 九、听辨、排练与评价工具\n| 轮次 | 时码/谱例 | 我听到的主题/变化 | 音乐要素 | 它怎样改变期待 | 仍不确定 |\n|---|---|---|---|---|---|\n|  |  |  |  |  |  |\n\n微型创编约束：8拍建立可识别规律，后8拍只改变一至两项要素；听众先预测再听。\n\n## 十、教学流程\n### 环节1｜无标题整体聆听（4分钟）\n学生个人画注意力变化线，不出现标题/故事。教师收集不同反应但追问音响位置。\n\n### 环节2｜捕捉主题并追踪重复（7分钟）\n教师提供经核主题短谱/图形谱，学生模唱/手势后复听，在结构条标出现。不会唱者用节奏/指向等价。把伴奏当新主题者回到核心音型比较。\n\n### 环节3｜意外之前发生了什么（7分钟）\n聚焦意外点之前，学生写“我预测下一次___，因为前面___”。再听意外前后，分别标力度、音色/配器、织体等经核变化。只说“大声”者补期待证据。\n\n### 环节4｜小组微型听觉实验（8分钟）\n每人先写一项规律/变化，再组合16拍声势/器乐。首演前听众写预测；首演后用“是否形成规律—改变何要素—是否可听出”反馈。\n\n### 环节5｜修订复演并反向验证作品（6分钟）\n小组只改一项，复演；随后再次听原作，学生比较自己的策略与作品。若首版有效，可精炼而不必造错。\n\n### 环节6｜标题、文化与证据边界（6分钟）\n教师提供经核作者/体裁/标题来源；轶事若证据不足标“流传说法”。学生判断标题如何影响预期，同时写即使不知道故事，音响仍能支持什么。\n\n### 环节7｜完整复听与迁移短评（7分钟）\n完整/较完整节选复听，个人CER：`在___位置，先通过___建立期待，再用___改变，因此我理解___；标题故事不能代替___。`新片段再判一次。\n\n**总时间：4+7+7+8+6+6+7=45分钟。**\n\n## 十一、板书与音乐成果\n```text\n“惊愕”不是一个大声点，而是期待关系\n主题/规律（重复）→ 我预测___ → 变化（力度/音色/织体…）→ 期待被打破\n位置证据 + 音乐要素 + 表现作用\n音响先于标题；轶事需核来源\n```\n\n## 十二、量规、差异化与作业\n| 维度 | 3级 | 2级 | 1级 |\n|---|---|---|---|\n| 结构听辨 | 主题及变化位置清楚 | 能听主题 | 只等突发点 |\n| 要素解释 | 两项以上证据解释期待 | 有一项证据 | 只讲故事/感受 |\n| 表现验证 | 规律与改变可听且复演改进 | 可听但关系弱 | 只追求响/搞笑 |\n| 评述 | 位置—要素—作用一致 | 有证据短评 | 背标题知识 |\n\n读谱弱者用图形谱，听觉差异者用振动/视觉结构辅助但保留音乐比较，行动困难者负责音型/指挥/结构卡。作业选合法音源找一处“预期—变化”，写时码和证据；无设备者用教师提供谱例，15分钟。\n\n## 十三、反思与核验\n- 收集个人结构线、证据卡、创编首版/复演和CER。\n- 风险：副标题猎奇、危险大音量、创编变搞笑；用无标题首听、音量门禁、可听标准纠偏。\n- 核验乐章、谱/音源版本、时码、主题/曲式/配器、标题与轶事来源、版权。\n- 下一课迁移到变奏或另一作品的重复—变化结构。","content_hash":"60da45dc8b81ae9cfcd2d744dbc13929cb12c1eb067f88e9dbca969f6a92b1bd","load_mode":"always","max_chars":2637,"sort_order":40,"metadata":{"source_package":"music-public-lesson-design","runtime_role":"discipline_reference","stages":["初中"]}},{"path":"references/excellent-example-senior.md","name":"高中音乐优秀教案样例","description":"基于公开教学主题重构的调式调性听觉探究与文化边界示范","media_type":"text/markdown","content":"# 高中音乐优秀教案参考样例\n\n> 依据人教社公开教学设计真实主题“培养聆听的耳朵——调式、调性”及高中音乐鉴赏机制原创重构，不复制原教案。正式实施须以当前教材、经校勘谱例和合法录音核准作品、片段、调式/调性结论及时码。\n\n## 一、课程基本信息\n| 字段 | 内容 |\n|---|---|\n| 学段/年级 | 高中一年级 |\n| 课题 | 培养聆听的耳朵——调式、调性 |\n| 课型/时长 | 音乐鉴赏与听觉探究，45分钟 |\n| 主导模式 | 听赏与评述（辅以演唱/键盘验证） |\n| 核心问题 | 我们怎样从音响证据感知“中心感”和调式色彩，而不是给作品贴情绪标签？ |\n| 证据状态 | 主题可核；教材作品、理论层级、谱例/音源待核 |\n\n## 二、单元与教材定位\n本课服务高中鉴赏方法：从泛泛情绪描述走向有意识聆听音乐语言。学生应具备基本音高/旋律经验；本课不以和声分析深度炫技，而以听觉—哼唱/弹奏—谱例—比较建立概念，后续迁移到风格和作品分析。\n\n## 三、作品、音响与文化分析\n- 按教材选2—3个短例，控制旋律、节奏等混杂变量的程度，并提供中心音/终止感、音阶/特征音等经核证据。\n- “大调快乐/小调悲伤”只能作为待质疑的初始经验，调式与情绪不存在一一决定关系；速度、节奏、力度、音色、和声、语境共同作用。\n- 区分调式（音级关系/组织方式）与调性（具体中心音高等，按教材定义）；不同理论传统不可强套同一框架。\n- 中国民族调式/其他文化音乐须使用适切理论和权威来源，不能只按西方大小调判断“缺音”。\n\n## 四、学情与音乐起点\n学生会以“明亮/忧伤”猜大小调，未必能感受中心/终止；有钢琴基础者易用术语压过听觉。诊断4分钟：听两个经核短例，先哼最终稳定音/选择终止是否完整，再写情绪但注明证据。术语正确却听辨失败者仍需参与听觉任务。\n\n## 五、核心增长与目标—任务—证据\n**核心增长**：从情绪标签推断调式，走向用中心感、音级关系和对比听辨构建概念，并说明调式与情感表达的非决定关系及文化边界。\n\n| 目标 | 任务 | 个体证据 | 标准 |\n|---|---|---|---|\n| 感知中心 | 终止/续接听辨 | 个人中心音选择与信心 | 能经复听修订 |\n| 比较调式 | 控制变量短例 | 听辨矩阵 | 引用可听/谱例证据 |\n| 验证概念 | 哼唱/键盘/音频改写 | V1—盲听反馈—V2及再次验证记录 | 知道改变什么、保持什么，并能据反馈单项修订 |\n| 文化评述 | 新作品边界判断 | CER | 不把大小调/情绪标签普遍化 |\n\n## 六、重难点与音乐实践链\n`整体听→中心感预测→哼唱/续接→谱例对应→控制变量比较→概念命名→音级改写验证→复听修订→跨文化边界→迁移评述`。难点是听觉与理论双向连接，并反对“大调快乐小调悲伤”绝对化。\n\n## 七、主导模式与公开课主线\n四轮聆听从中心、调式对比、改写验证到完整作品回归。教师键盘仅用于学生预测后的即时验证；乐理强者不能替全班回答。最终成果是个人听辨矩阵和有边界评述。\n\n## 八、音源乐谱、器材、安全与版权\n正式列作品/版本/演奏者/时码/谱例来源、教学改写说明；键盘或合法音源，音量安全。无键盘用预制经核对比音频。学生不被强迫独唱，可哼唱、手势、键盘单音或谱例指认；变声期自由选择。录音不含个人考核公开展示。\n\n## 九、听辨、排练与评价工具\n| 片段 | 我的中心感/终止判断 | 调式猜测与信心 | 音响/谱例证据 | 其他要素 | 复听后修订 | 适用边界 |\n|---|---|---|---|---|---|---|\n|  |  |  |  |  |  |  |\n\n改写表：保持节奏/速度/音色等，明确只改变经核音级；实际音响若未控制变量，不得据此作单因实验结论。\n\n## 十、教学流程\n### 环节1｜情绪标签可靠吗（4分钟）\n听两例，个体写情绪与调式猜测、信心。教师暂不公布，标记“依据是情绪还是音高关系”。\n\n### 环节2｜寻找中心与终止感（7分钟）\n片段停在未终止/终止位置，学生哼或选“最想落到的音”，复听比较。声乐不便者用编号/手势；不同答案回音响验证。\n\n### 环节3｜谱例连接与概念命名（6分钟）\n在已有听觉经验后呈现经核短谱，标中心和音级关系，区分调式/调性（按教材层级）。不做脱离音响的抄定义。\n\n### 环节4｜控制变量对比听辨（8分钟）\n播放教师预制、经核且标“教学改写”的A/B，说明保持和改变项。每人填矩阵，再小组比较。若音色/力度未实际相同，必须写混杂，不能假称严格控制。\n\n### 环节5｜学生改写、盲听反馈与V2复验（7分钟）\n使用给定2—4小节素材，每人先标拟改音级；小组用哼唱、键盘或经核音频实现V1，另一组在不知道版本标签时听辨并写“判断—中心/音级证据—仍含糊处”。原组只能依据反馈修改一个音级或一个经核变量，保留V1并形成V2，再次演唱、演奏或播放；盲听组复判“证据是否更清楚、是否引入新问题”。若V1已清楚，可做一项精炼并解释保留理由，不强迫制造错误。素材/实现来源明确，AI/软件自动和声不冒充学生创作。\n\n### 环节6｜回到完整作品和文化边界（7分钟）\n聆听较完整片段，学生检查调式只是表达资源之一；比较另一文化传统时先用其适切来源/术语，不将大小调框架强套。文化背景用于解释，不先替学生规定感受。\n\n### 环节7｜迁移评述与出口（6分钟）\n新片段CER：`我暂判断___，证据是中心感/音级___；情绪还受到___影响；这套判断在___文化/材料边界内适用，仍需___。`回看开场信心并允许修订。\n\n**总时间：4+7+6+8+7+7+6=45分钟。**\n\n## 十一、板书与音乐成果\n```text\n情绪标签 → 不足以推出调式\n听中心/终止 → 看音级关系 → 比较调式 → 改写验证 → 回到整体作品\n调式/调性（按教材定义）\n调式 + 节奏/速度/力度/音色/和声/语境 → 综合表达\n理论有文化边界\n```\n\n## 十二、量规、差异化与作业\n| 维度 | 3级 | 2级 | 1级 |\n|---|---|---|---|\n| 听辨 | 中心/音级证据与信心校准 | 能做基本判断 | 只靠情绪猜 |\n| 理论连接 | 听觉—谱例—概念一致 | 会术语但证据弱 | 抄定义 |\n| 验证 | 改写变量清楚并据盲听修订 | 有改写 | 软件代做/假控制 |\n| 文化评述 | 说明多要素与理论边界 | 能避免绝对化 | 大调快乐小调悲伤/强套体系 |\n\n读谱弱者用听觉/编号图，绝对音感者也须解释关系而非报音名，变声期用非独唱路径，听觉困难者获视觉谱例和振动/辅助听觉且按可及目标评价。作业选教材合法片段写中心感与两项证据，不确定可标信心和待核，15分钟。\n\n## 十三、反思与核验\n- 收集诊断/复听矩阵、V1—反馈—V2改写与再次验证记录、盲听证据和CER。\n- 风险：术语压过聆听、假控制变量、文化体系强套；以音响先行、改写说明、适切理论纠偏。\n- 核验教材定义、作品与录音、调式/调性、中心音、谱例、改写音频、时码、文化来源和许可。\n- 下一课迁移到作品风格/和声色彩，继续标判断信心和证据边界。","content_hash":"257834348eb777ee8a1af5c6fdbfd0effe5032ab3f4b9f506ceb4d252a2ab05e","load_mode":"always","max_chars":2992,"sort_order":50,"metadata":{"source_package":"music-public-lesson-design","runtime_role":"discipline_reference","stages":["高中"]}},{"path":"references/sources-and-boundaries.md","name":"音乐 Skill 来源与边界","description":"义教/高中课标、精品课、谱例音源、文化版权与安全边界","media_type":"text/markdown","content":"# 音乐 Skill 来源与边界\n\n- [教育部《义务教育艺术课程标准（2022年版）》入口](https://www.moe.gov.cn/srcsite/A26/s8001/202204/t20220420_619921.html)：四项艺术核心素养及音乐“欣赏、表现、创造、联系”内容与分学段任务的首要依据。\n- [普通高中课程方案和课程标准（2017年版2020年修订）通知](https://www.moe.gov.cn/srcsite/A26/s8001/202006/t20200603_462199.html)：高中音乐课程依据入口。\n- [2024年部级精品课名单](https://www.moe.gov.cn/jyb_xxgk/s5743/s5744/A06/202506/W020250624684887950733.pdf)：核对不同学段、版本、唱歌/欣赏等真实课题，不反推流程。\n- [人教社《培养聆听的耳朵——调式、调性》教学设计](https://www.pep.com.cn/zzggjc/ys2023/yyjsysj/jxsj/202308/t20230829_1986296.shtml) 和 [一年级备课建议](https://www.pep.com.cn/rjyy/rjyyxzx/xzx/202506/t20250617_2002126.html)：用于确认从音响/声音属性出发和高中有意识聆听方向，不复制其教案。\n\n当前项目没有音乐教材、乐谱或音频。正式生成须提供精确教材页、经校勘谱例、合法音源及版本；同名作品可能存在不同编配、调、速度、段落和时码。样例只用官方名单可确认的课题或课标机制原创重构，不宣称复刻获奖课。\n\n引用音频、谱例、歌词、译文、图片和视频须记录版权/许可，只截取教学必要部分；公开演示、录制和传播另核表演/录音录像权。民族民间与戏曲材料优先权威传承/研究机构，核语言、场合和文化主体，避免异域化。演唱演奏遵循嗓音、听力、身体和器材安全；学生录音最小化、经同意、限课堂、按期删除。","content_hash":"ca0fe6c7e699cf343bbaf7ca484c971e56b423ce275829c017a6a5f81c5a3ae0","load_mode":"always","max_chars":873,"sort_order":60,"metadata":{"source_package":"music-public-lesson-design","runtime_role":"discipline_reference"}},{"path":"agents/openai.yaml","name":"OpenAI Skill 界面配置","description":"源包界面元数据，不进入生成上下文","media_type":"application/yaml","content":"interface:\n  display_name: \"音乐公开课设计\"\n  short_description: \"以聆听证据、音乐表现和创造修订设计分学段音乐公开课\"\n  default_prompt: \"请依据教材与音响证据设计以音乐实践为核心的完整公开课。\"","content_hash":"3bf6e2791ef179ac643d9f50c4a45dccbc5e13a76e17e355d8bada6ce10673ec","load_mode":"evaluation_only","max_chars":133,"sort_order":70,"metadata":{"source_package":"music-public-lesson-design","runtime_role":"evaluation_only"}}],"skill_description":"完整小学、初中、高中音乐公开课设计 Skill：从音响出发，以多次有目的聆听、音乐表现或创造、反馈复演和文化证据组织学习。","match_criteria":{"subjects":["音乐"],"lesson_types":["公开课"]}}$subjectskill$::jsonb;
  v_skill_id uuid;
  v_version_id uuid;
begin
  select id into v_skill_id
  from public.hai_work_skills
  where slug = v_payload->>'skill_slug';

  if v_skill_id is null then
    raise exception 'Work Skill 不存在：%', v_payload->>'skill_slug';
  end if;

  if exists (
    select 1 from public.hai_work_skill_versions
    where skill_id = v_skill_id
      and version_label = v_payload->>'version_label'
      and status in ('published', 'archived')
  ) then
    raise exception '同名学科 Work Skill 版本已冻结：%', v_payload->>'version_label';
  end if;

  update public.hai_work_skill_versions
  set status = 'archived', updated_at = now()
  where skill_id = v_skill_id and status = 'published';

  insert into public.hai_work_skill_versions (
    skill_id, version_label, status, prompt_template, default_prompt_template,
    input_contract, output_contract, snapshot_hash, source_metadata, published_at
  ) values (
    v_skill_id,
    v_payload->>'version_label',
    'draft',
    v_payload->>'instructions',
    v_payload->>'instructions',
    v_payload->'input_contract',
    v_payload->'output_contract',
    v_payload->>'snapshot_hash',
    v_payload->'source_metadata',
    null
  )
  on conflict (skill_id, version_label) do update set
    status = 'draft',
    prompt_template = excluded.prompt_template,
    default_prompt_template = excluded.default_prompt_template,
    input_contract = excluded.input_contract,
    output_contract = excluded.output_contract,
    snapshot_hash = excluded.snapshot_hash,
    source_metadata = excluded.source_metadata,
    published_at = null,
    updated_at = now()
  returning id into v_version_id;

  delete from public.hai_work_skill_references where skill_version_id = v_version_id;

  insert into public.hai_work_skill_references (
    skill_version_id, path, name, description, media_type, content,
    content_hash, load_mode, max_chars, sort_order, metadata
  )
  select
    v_version_id, item.path, item.name, item.description, item.media_type,
    item.content, item.content_hash, item.load_mode, item.max_chars,
    item.sort_order, item.metadata
  from jsonb_to_recordset(v_payload->'references') as item(
    path text, name text, description text, media_type text, content text,
    content_hash text, load_mode text, max_chars integer, sort_order integer,
    metadata jsonb
  );

  update public.hai_work_skill_versions
  set status = 'published', published_at = now(), updated_at = now()
  where id = v_version_id;

  update public.hai_work_skills
  set name = '音乐公开课设计 Skill',
      description = v_payload->>'skill_description',
      match_criteria = v_payload->'match_criteria',
      is_fallback = false,
      is_enabled = true,
      updated_at = now()
  where id = v_skill_id;

  perform public.hai_recompute_work_module_enabled('subject-lesson-design');
end;
$$;

commit;
